<?php
namespace App\Http\Controllers\ScannerApi;
use App\Http\Controllers\Controller;use App\Models\OrganizerStaff;use App\Models\Event;use App\Services\Tickets\TicketAdmissionService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class StaffScannerController extends Controller{
 public function login(Request $r){$d=$r->validate(['organizer_id'=>'required|integer','username'=>'required|string','password'=>'required|string','device_name'=>'nullable|string']);$s=OrganizerStaff::where('organizer_id',$d['organizer_id'])->where('username',$d['username'])->where('active',1)->first();if(!$s||!Hash::check($d['password'],$s->password)||!$s->hasPermission('tickets.scan'))return response()->json(['status'=>'error','message'=>'Invalid scanner credentials'],401);if($s->must_change_password)return response()->json(['status'=>'error','message'=>'Password change required'],403);$s->tokens()->where('name',$d['device_name']??'scanner')->delete();return response()->json(['status'=>'success','role'=>'staff','staff'=>['id'=>$s->id,'name'=>$s->name,'role'=>$s->role],'token'=>$s->createToken($d['device_name']??'scanner')->plainTextToken]);}
 public function events(){ $s=auth('staff_sanctum')->user();if(!$s->active||!$s->hasPermission('tickets.scan'))abort(403);$ids=$s->assignments()->pluck('event_id');return response()->json(['status'=>'success','events'=>Event::where('organizer_id',$s->organizer_id)->whereIn('id',$ids)->get(['id','slug','event_type','box_office_enabled','reentry_policy','max_reentries'])]);}
 public function scan(Request $r,TicketAdmissionService $svc){$d=$r->validate(['booking_id'=>'required|string|max:255','direction'=>'nullable|in:entry,exit']);$s=auth('staff_sanctum')->user();return response()->json($svc->admit($d['booking_id'],'staff',$s->id,$r->header('X-Device-Name'),$r->ip(),$d['direction']??'entry'));}
 public function logout(Request $r){$r->user('staff_sanctum')->currentAccessToken()->delete();return response()->json(['status'=>'success']);}
}